"""Original offline fake-provider response fixture; NOT generated by a model."""

import json
from pathlib import Path

lines = Path('/work/input.txt').read_text().splitlines()
assert lines[0].startswith('SYNTHETIC EXAMPLE')
fields = {}
items = []
for line in lines[1:]:
    line = line.strip()
    if not line:
        continue
    if line.startswith('Item:'):
        parts = dict(part.strip().split(':', 1) for part in line.split('|'))
        items.append({'description': parts['Item'].strip(),
                      'quantity': int(parts['Quantity']),
                      'unit_cents': int(parts['Unit cents'])})
    else:
        key, value = line.split(':', 1)
        fields[key.strip()] = value.strip()
result = {'synthetic': True, 'document_id': fields['Document'], 'supplier': fields['Supplier'],
          'date': fields['Date'], 'currency': fields['Currency'], 'items': items,
          'total_cents': sum(item['quantity'] * item['unit_cents'] for item in items)}
Path('/work/out/result.json').write_text(json.dumps(result, ensure_ascii=False))
